1	import {once} from 'node:events';
2	import type {AddressInfo} from 'node:net';
3	import {WebSocket} from 'ws';
4	import type {Express} from 'express';
5	import {createServer} from './createServer.js';
6	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
7	import type {SessionResumeOptions} from './ws/sessionResume.js';
8	import {answeringOrchestrator} from './wsTestSupport.js';
9	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
10	import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
11	import type {MessageChunk} from '../types/ai.js';
12	import type {ConnectedMessage} from '../types/messages.js';
13	import type {SessionEntry} from '../types/session.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {setLogger} from '../shared/logger.js';
16	
17	// Real upgrades over a real socket: what a reconnect is sent is the contract, and no double can observe it.
18	
19	interface Frame {
20	  type: string;
21	  sessionId?: string;
22	  resumed?: boolean;
23	  entryCount?: number;
24	  resumeFailure?: string;
25	  index?: number;
26	  entry?: SessionEntry;
27	}
28	
29	const NEVER_ISSUED = '0f1e2d3c-4b5a-4968-8776-655443322110';
30	const RESUME_ON: SessionResumeOptions = {enabled: true};
31	const LATEST_ON: SessionResumeOptions = {enabled: true, latest: true};
32	const HALF_ANSWER: SessionEntry = {
33	  role: 'assistant',
34	  content: 'half',
35	  timestamp: '2026-09-30T08:00:01.000Z',
36	  isStreaming: true,
37	};
38	
39	// A tool's suppression lands while the answer is still open, as when a provider ends a tool round with no stop.
40	const suppressingMidAnswer: ChatOrchestrator = {
41	  processMessage: async () => 'before after',
42	  async *processMessageStream(): AsyncGenerator<MessageChunk> {
43	    yield {type: 'text', text: 'before'};
44	    yield {type: 'suppress_output'} as unknown as MessageChunk;
45	    yield {type: 'text', text: ' after'};
46	    yield {type: 'stop', stopReason: 'end_turn'};
47	  },
48	};
49	
50	const servers: Array<ReturnType<typeof createServer>> = [];
51	const clients: WebSocket[] = [];
52	
53	const eventually = async (check: () => boolean): Promise<void> => {
54	  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
55	};
56	
57	// Silenced for the whole file: the server logs every connection and close, and these tests read frames, not logs.
58	beforeAll(() => {
59	  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
60	});
61	
62	afterAll(() => {
63	  setLogger();
64	});
65	
66	// Each server sees its sockets close before it stops, so no close is logged after the logger above is restored.
67	afterEach(async () => {
68	  for (const client of clients.splice(0)) client.terminate();
69	  for (const hal of servers.splice(0)) {
70	    const {wss} = hal;
71	    await eventually(() => wss.clients.size === 0);
72	    await hal.stop();
73	  }
74	});
75	
76	// The authenticated user is read per upgrade, so one test can reconnect as someone else.
77	const startEngine = async (
78	  store: SessionStore,
79	  resume?: SessionResumeOptions,
80	  orchestrator: ChatOrchestrator = answeringOrchestrator
81	) => {
82	  const auth = {userId: 'u1'};
83	  const connects: Array<{sessionId: string; resumed: boolean}> = [];
84	  const disconnected: string[] = [];
85	  const hal = createServer({
86	    app: (() => undefined) as unknown as Express,
87	    wsAuth: async () => ({id: auth.userId}),
88	    sessionStore: store,
89	    orchestrator,
90	    resume,
91	    onConnect: (session, {resumed}) => void connects.push({sessionId: session.sessionId, resumed}),
92	    onDisconnect: sessionId => void disconnected.push(sessionId),
93	  });
94	  // Resolves once the server itself has seen its first socket close, which the client's own close can precede.
95	  const firstServerClose = new Promise<void>(resolve => {
96	    hal.wss.once('connection', socket => socket.once('close', () => resolve()));
97	  });
98	  await hal.start(0);
99	  servers.push(hal);
100	  const {port} = hal.server.address() as AddressInfo;
101	  return {auth, connects, disconnected, firstServerClose, base: `ws://127.0.0.1:${port}/hal/ws`};
102	};
103	
104	const open = (url: string, token = 't'): WebSocket => {
105	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
106	  clients.push(client);
107	  return client;
108	};
109	
110	// One question answered and the socket closed, returning the id the connected frame announced.
111	const firstTurn = async (base: string): Promise<string> => {
112	  const client = open(base);
113	  let sessionId = '';
114	  await new Promise<void>(resolve => {
115	    client.on('message', raw => {
116	      const frame = JSON.parse(String(raw)) as Frame;
117	      if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
118	      if (frame.type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
119	      if (frame.type === 'stream_end') resolve();
120	    });
121	  });
122	  client.close();
123	  await once(client, 'close');
124	  return sessionId;
125	};
126	
127	// A ping sent on connect is a barrier: its pong can only follow every frame the replay wrote.
128	const connectAndSettle = async (url: string, token?: string): Promise<Frame[]> => {
129	  const client = open(url, token);
130	  const frames: Frame[] = [];
131	  await new Promise<void>(resolve => {
132	    client.on('message', raw => {
133	      const frame = JSON.parse(String(raw)) as Frame;
134	      frames.push(frame);
135	      if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 1}));
136	      if (frame.type === 'pong') resolve();
137	    });
138	  });
139	  return frames;
140	};
141	
142	const upserts = (frames: Frame[]) =>
143	  frames.filter(frame => frame.type === 'entry_upsert').map(({index, entry}) => ({index, entry}));
144	
145	const shapeOf = (frames: Frame[]) => ({
146	  keys: Object.keys(frames[0]).sort(),
147	  resumed: frames[0].resumed,
148	  resumeFailure: frames[0].resumeFailure,
149	  types: frames.map(frame => frame.type),
150	});
151	
152	const deferredRelease = () => {
153	  let release = (): void => undefined;
154	  const until = new Promise<void>(resolve => {
155	    release = resolve;
156	  });
157	  return {until, release: () => release()};
158	};
159	
160	// Each stored conversation holds one user entry, sent at the given time and reading as its own id.
161	const storeWith = (conversations: Array<[sessionId: string, userId: string, sentAt: string]>): InMemorySessionStore => {
162	  const store = new InMemorySessionStore();
163	  for (const [sessionId, userId, sentAt] of conversations) {
164	    const {entries} = store.create(sessionId, userId);
165	    entries.push({role: 'user', content: sessionId, timestamp: sentAt});
166	  }
167	  return store;
168	};
169	
170	// A store with only the required members, so an optional one can be added, replaced or left out per test.
171	const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
172	  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
173	  get: sessionId => inner.get(sessionId),
174	  delete: sessionId => inner.delete(sessionId),
175	  count: () => inner.count(),
176	  clear: () => inner.clear(),
177	});
178	
179	describe('resuming a conversation on reconnect', () => {
180	  it('with resume absent, answers a reconnect naming the first id with a new id and no replay', async () => {
181	    const {base} = await startEngine(new InMemorySessionStore());
182	    const first = await firstTurn(base);
183	
184	    const frames = await connectAndSettle(`${base}?sessionId=${first}`);
185	
186	    expect({newId: frames[0].sessionId !== first, shape: shapeOf(frames)}).toEqual({
187	      newId: true,
188	      shape: {
189	        keys: ['examplePrompts', 'message', 'sessionId', 'type'],
190	        resumed: undefined,
