// The user is the connection's own, never a field of the frame; a store without listFor is answered, not an empty list.
async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  request: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'This server cannot list conversations');
    return;
  }
  try {
    const summaries = await sessionStore.listFor(session.userId, {limit: request.limit, before: request.before});
    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'conversation list failed', {sessionId: session.sessionId, userId: session.userId, error: message});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

